def e(value): return html.escape(str(value), quote=True)
def asset(name): return '/assets/' + name
def picture(name, alt='', cls='', eager=False):
    return f'<img class="{cls}" src="{asset(name)}" alt="{e(alt)}" loading="{'eager' if eager else 'lazy'}" decoding="async">'
def link(text, url, variant='outline'):
    return f'<a class="btn btn-{variant}" href="{url}">{text}<span aria-hidden="true">↗</span></a>'
def eyebrow(text): return f'<span class="eyebrow">{text}</span>'
def section_head(kicker, title, text='', action=''):
    return f'<div class="section-head">{eyebrow(kicker)}<div class="section-head-row"><h2>{title}</h2><div>{f"<p>{text}</p>" if text else ""}{action}</div></div></div>'
def intro(kicker, title, text, image_name='', alt=''):
    media=f'<div class="page-cover">{picture(image_name, alt)}</div>' if image_name else ''
    return f'<section class="page-intro wrap">{eyebrow(kicker)}<h1>{title}</h1><p>{text}</p>{media}</section>'

