 ('About', '/about/', [('Our company','/about/'),('Leadership','/about/leadership/'),('Our approach','/about/approach/'),('Careers','/careers/')]),
 ('Portfolio','/portfolio/', [('All projects','/portfolio/'),('Residential','/portfolio/?type=Residential'),('Mixed use & land','/portfolio/?type=Land%20%26%20mixed-use'),('Commercial & industrial','/capabilities/')]),
 ('Capabilities','/capabilities/', [('Development','/capabilities/#development'),('Acquisitions','/acquisitions/'),('Land development','/capabilities/#land'),('Asset strategy','/capabilities/#asset')]),
 ('Partnerships','/partners/', [('Capital partners','/partners/capital/'),('Landowners','/partners/landowners/'),('Brokers','/partners/brokers/'),('Municipalities','/partners/municipalities/'),('Submit an opportunity','/acquisitions/#submission')]),
