def project_card(p):
    return f'''<article class="project-card" data-project data-type="{e(p['sector'])}" data-stage="{e(p['status'])}" data-search="{e((p['title']+' '+p['location']+' '+p['sector']).lower())}"><a class="project-image" href="{project_url(p)}">{picture(p['image'],p['imageNote']+' for '+p['title'])}<span class="image-chip">{e(p['imageNote'])}</span></a><div class="project-meta"><span>{e(p['sector'])}</span><span>{e(p['status'])}</span></div><h3><a href="{project_url(p)}">{e(p['title'])}</a></h3><div class="project-bottom"><span>{e(p['location'])}<br><small>{e(p['scale'])}</small></span><a href="{project_url(p)}" aria-label="Explore {e(p['title'])}">↗</a></div></article>'''

def map_section():
    pins=[('Lifestyle Enclave','Upper Hammonds Plains','/portfolio/lifestyle-enclave/','55%','47%'),('Two River','Mineville','/portfolio/two-river-mineville/','53%','46%'),('Cornwallis Park','Annapolis County','/portfolio/cornwallis-park/','17%','46%')]
    buttons=''.join(f'<a class="map-pin" style="--x:{x};--y:{y}" href="{url}" aria-label="{name}, {place}. View project"><span class="pin-dot"></span><span class="pin-card"><strong>{name}</strong><small>{place}</small></span></a>' for name,place,url,x,y in pins)
    return f'''<section class="map-section section-dark" id="map"><div class="wrap">{section_head('OUR FOOTPRINT','Growing across Nova Scotia.','Explore locations represented in the documented portfolio. Pins indicate communities, not parcel boundaries.')}<div class="map-layout"><div class="map-frame">{picture('project-locations.webp','Published Nova Scotia location overview map; map markers are from earlier materials and are not a project legend')}{buttons}</div><div class="map-list"><span class="eyebrow">EXPLORE BY PLACE</span><a href="/portfolio/lifestyle-enclave/"><span>01</span> Upper Hammonds Plains <b>↗</b></a><a href="/portfolio/two-river-mineville/"><span>02</span> Mineville <b>↗</b></a><a href="/portfolio/cornwallis-park/"><span>03</span> Annapolis County <b>↗</b></a><p>Additional names in earlier public materials require confirmation before they can be mapped as current projects.</p></div></div></div></section>'''

