def approach():
    parts=[('Local intelligence','Understand Nova Scotia’s development context and the needs of each community.'),('Integrated thinking','Consider land, planning, financing, construction and operations together.'),('Partnership mindset','Work constructively with landowners, brokers, specialists, capital sources and public stakeholders.'),('Long-term perspective','Assess how an asset or place functions beyond its first transaction.')]
