    form=f'''<form class="lead-form" data-mail-form data-subject="Plexus website enquiry"><div class="form-grid">{fields}</div><label>How can we help? <span>*</span><textarea name="message" rows="6" required></textarea></label><label class="check"><input type="checkbox" name="consent" required><span>I consent to Plexus Development Group contacting me about this enquiry.</span></label><div class="form-honey" aria-hidden="true"><label>Leave blank<input name="website" tabindex="-1" autocomplete="off"></label></div><button class="btn btn-gold" type="submit">Prepare enquiry email <span aria-hidden="true">↗</span></button>{form_note()}<p class="form-status" role="status"></p></form>'''
    return intro('CONTACT','Start a <em>conversation.</em>','Tell us what brings you here and we will connect you with the right next discussion.')+f'''<section class="section wrap contact-layout"><div><h2>Let’s talk about what comes next.</h2><p>Head office</p><address>3845 Joseph Howe Drive, Suite 100<br>Halifax, Nova Scotia</address><a href="tel:+19028099399">+1 902 809 9399</a><a href="mailto:{EMAIL}">{EMAIL}</a><div class="contact-visual">{picture('halifax-hero.webp','Aerial view of the Halifax waterfront in Nova Scotia')}</div></div>{form}</section>'''

