def ld_json(route,title):
    org={'@context':'https://schema.org','@type':'Organization','name':'Plexus Development Group','url':ORIGIN+'/','email':EMAIL,'telephone':'+1-902-809-9399','address':{'@type':'PostalAddress','streetAddress':'3845 Joseph Howe Drive, Suite 100','addressLocality':'Halifax','addressRegion':'NS','addressCountry':'CA'}}
    crumbs=route.split('/') if route else []
    items=[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'}]
    for i in range(len(crumbs)):
        path='/'.join(crumbs[:i+1]);items.append({'@type':'ListItem','position':i+2,'name':crumbs[i].replace('-',' ').title(),'item':ORIGIN+'/'+path+'/'})
    return '<script type="application/ld+json">'+json.dumps(org,ensure_ascii=False).replace('<','\\u003c')+'</script>'+('<script type="application/ld+json">'+json.dumps({'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':items},ensure_ascii=False)+'</script>' if route else '')

def write(route,title,body,description):
    path=OUT/route/'index.html';path.parent.mkdir(parents=True,exist_ok=True)
    url=ORIGIN+'/'+(route+'/' if route else '')
    robots='index,follow,max-image-preview:large' if LAUNCH else 'noindex,nofollow'
    markup=f'''<!doctype html><html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | Plexus Development Group</title><meta name="description" content="{e(description)}"><meta name="robots" content="{robots}"><meta name="theme-color" content="#101d2b"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:site_name" content="Plexus Development Group"><meta property="og:title" content="{e(title)} | Plexus Development Group"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/og-image.png"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/logo.png"><link rel="stylesheet" href="/revamp.css"><script src="/revamp.js" defer></script>{ld_json(route,title)}</head><body id="top">{header()}<main id="main">{body}</main>{footer()}</body></html>'''
    path.write_text(markup)

for route,(title,fn,description) in PAGES.items(): write(route,title,fn(),description)

